// Kill switch for the old Jekyll (Chirpy) site's service worker
// (REDESIGN_PLAN.md Phase 7). The old site registered /sw.min.js and cached
// its pages, so returning visitors could keep seeing it. Browsers re-fetch this
// URL to check for updates. This version takes over at once, deletes every
// cache, unregisters itself and reloads open tabs, which then load the new
// site from the network. It has no fetch handler, so it never serves a page.
// Keep it at this path until at least May 2027.
self.addEventListener('install', () => {
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.map((key) => caches.delete(key)));
      await self.registration.unregister();
      const tabs = await self.clients.matchAll({ type: 'window' });
      await Promise.all(tabs.map((tab) => tab.navigate(tab.url)));
    })(),
  );
});
